/// <summary>
/// Transfer order load planning aid report UI builder
/// </summary>
class METTransferOrderLoadPlanningAidUIBuilder extends SrsReportDataContractUIBuilder
{
    METTransferOrderLoadPlanningAidContract    contract;

}

Method.Source:
/// <summary>
/// Maps dialog fields for validation
/// </summary>
public void postBuild()
{
    super();
    contract = this.dataContractObject() as METTransferOrderLoadPlanningAidContract;

    DialogField dateFromDialogField = this.bindInfo().getDialogField(contract, methodStr(METTransferOrderLoadPlanningAidContract, parmConfirmedShipDateFrom));
    DialogField dateToDialogField = this.bindInfo().getDialogField(contract, methodStr(METTransferOrderLoadPlanningAidContract, parmConfirmedShipDateTo));
    dateFromDialogField.fieldControl().mandatory(true);
    dateToDialogField.fieldControl().mandatory(true);  
}
